import json

def pair_sum(items, target):
    left, right = 0, len(items) - 1
    while left < right:
        total = items[left] + items[right]
        if total == target:
            return [left, right]
        if total < target:
            left += 1
        else:
            right -= 1
    return []

print(json.dumps(pair_sum([-2, 0, 0, 2], 0), separators=(",", ":")))
print(json.dumps(pair_sum([2], 4)))

function pairSum(items, target) {
  let left = 0, right = items.length - 1;
  while (left < right) {
    const total = items[left] + items[right];
    if (total === target) return [left, right];
    if (total < target) left++;
    else right--;
  }
  return [];
}
console.log(JSON.stringify(pairSum([-2, 0, 0, 2], 0)));
console.log(JSON.stringify(pairSum([2], 4)));

function maxWindow(items, k) {
  if (k === 0) return 0;
  let current = 0;
  for (let i = 0; i < k; i++) current += items[i];
  let best = current;
  for (let right = k; right < items.length; right++) {
    current += items[right] - items[right - k];
    best = Math.max(best, current);
  }
  return best;
}
console.log(maxWindow([1, 2, 8], 2));
console.log(maxWindow([-5, -2, -4], 2));
console.log(maxWindow([], 0));

def direct(items, k):
    if k == 0:
        return [0, 0]
    best, reads = None, 0
    for start in range(len(items) - k + 1):
        total = 0
        for i in range(start, start + k):
            total += items[i]
            reads += 1
        if best is None or total > best:
            best = total
    return [best, reads]

def sliding(items, k):
    if k == 0:
        return [0, 0]
    current = 0
    for i in range(k):
        current += items[i]
    best, reads = current, k
    for right in range(k, len(items)):
        current += items[right] - items[right - k]
        reads += 2
        best = max(best, current)
    return [best, reads]

