function direct(items, k) {
  if (k === 0) return [0, 0];
  let best = null, reads = 0;
  for (let start = 0; start <= items.length - k; start++) {
    let total = 0;
    for (let i = start; i < start + k; i++) {
      total += items[i];
      reads++;
    }
    if (best === null || total > best) best = total;
  }
  return [best, reads];
}
function sliding(items, k) {
  if (k === 0) return [0, 0];
  let current = 0;
  for (let i = 0; i < k; i++) current += items[i];
  let best = current, reads = k;
  for (let right = k; right < items.length; right++) {
    current += items[right] - items[right - k];
    reads += 2;
    best = Math.max(best, current);
  }
  return [best, reads];
}
console.log(...direct([1, 2, 3, 4, 5], 3));
console.log(...sliding([1, 2, 3, 4, 5], 3));
