import json

def word_counts(text):
    counts = {}
    for word in text.split(" "):
        if word:
            counts[word] = counts.get(word, 0) + 1
    return [[word, count] for word, count in counts.items()]

print(json.dumps({"result": word_counts("red blue red")}, separators=(",", ":")))
print(json.dumps({"result": word_counts("   ")}, separators=(",", ":")))

function wordCounts(text) {
  const counts = new Map();
  for (const word of text.split(" ")) {
    if (word !== "") counts.set(word, (counts.get(word) ?? 0) + 1);
  }
  return Array.from(counts);
}
console.log(JSON.stringify({result: wordCounts("red blue red")}));
console.log(JSON.stringify({result: wordCounts("   ")}));

